const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const brazil = ee.FeatureCollection("FAO/GAUL/2015/level0")
      .filter(ee.Filter.eq('ADM0_NAME', 'Brazil'))
      .first()
      .geometry();

    const year2003 = 2003;
    const year2019 = 2019;

    // 2. Data Acquisition
    // MapBiomas Collection 7.0 for land cover classification
    const mapbiomas = ee.ImageCollection('projects/mapbiomas-workspace/public/collection7/mapbiomas_collection70_1_year_mosaic');

    // Select images for the target years
    const image2003 = mapbiomas.filter(ee.Filter.eq('year', year2003)).first();
    const image2019 = mapbiomas.filter(ee.Filter.eq('year', year2019)).first();

    // Check if images were found for both years
    if (!image2003) {
      console.log(`No MapBiomas image found for ${year2003}.`);
      console.log("C1");
      return;
    }
    if (!image2019) {
      console.log(`No MapBiomas image found for ${year2019}.`);
      console.log("C1");
      return;
    }

    // MapBiomas Class 15 represents Agriculture
    const croplandClass = 15;

    // Create binary masks for cropland for each year
    const cropland2003 = image2003.select('classification').eq(croplandClass);
    const cropland2019 = image2019.select('classification').eq(croplandClass);

    // Calculate pixel area for each image where cropland is present
    const areaImage2003 = cropland2003.multiply(ee.Image.pixelArea()); // Area in square meters
    const areaImage2019 = cropland2019.multiply(ee.Image.pixelArea()); // Area in square meters

    // Define reduction parameters
    const scale = 1000; // Use a coarse scale to avoid memory issues for large regions
    const maxPixels = 1e10; // Increase maxPixels for large regions

    // Calculate total cropland area for each year
    const areaReducer = ee.Reducer.sum();

    const totalCropland2003_m2 = await areaImage2003.reduceRegion({
      reducer: areaReducer,
      geometry: brazil,
      scale: scale,
      maxPixels: maxPixels
    }).get('classification').getInfo();

    const totalCropland2019_m2 = await areaImage2019.reduceRegion({
      reducer: areaReducer,
      geometry: brazil,
      scale: scale,
      maxPixels: maxPixels
    }).get('classification').getInfo();

    // 3. Validation and Final Answer
    if (totalCropland2003_m2 === null || totalCropland2019_m2 === null || isNaN(totalCropland2003_m2) || isNaN(totalCropland2019_m2)) {
      console.log("Calculation failure: Cropland area is None or NaN.");
      console.log("C3");
      return;
    }

    // Convert area from square meters to square kilometers
    const totalCropland2003_km2 = totalCropland2003_m2 / 1e6;
    const totalCropland2019_km2 = totalCropland2019_m2 / 1e6;

    // Check for valid pixel counts (implicit through area calculation)
    // If area is 0, it means no pixels were found for the class.
    if (totalCropland2003_km2 === 0 && totalCropland2019_km2 === 0) {
      console.log("No valid cropland pixels found for either 2003 or 2019 after processing.");
      console.log("C2");
      return;
    }

    // Output results
    console.log(`Cropland area in 2003: ${totalCropland2003_km2.toFixed(2)} km²`);
    console.log(`Cropland area in 2019: ${totalCropland2019_km2.toFixed(2)} km²`);

    if (totalCropland2019_km2 > totalCropland2003_km2) {
      console.log("A"); // Yes, cropland area increased
    } else {
      console.log("B"); // No, cropland area did not increase (stayed same or decreased)
    }

  } catch (error) {
    console.log("An error occurred during the analysis:");
    console.log(error.message);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
